app_css:
.tool-app-saltroute { color: #083344; max-width: 860px; margin-inline: auto; font-size: 14px; }
.tool-app-saltroute .sr-hidden { display: none !important; }
.tool-app-saltroute .sr-tabs { display: flex; gap: 6px; margin-bottom: 14px; }
.tool-app-saltroute .sr-tab { border: 1px solid #a5f3fc; background: #ecfeff; color: #0e7490; border-radius: 999px; padding: 8px 18px; font-weight: 700; font-size: 13px; cursor: pointer; }
.tool-app-saltroute .sr-tab.sr-active { background: #0e7490; color: #fff; border-color: #0e7490; }
.tool-app-saltroute h4 { margin: 16px 0 8px; font-size: 15px; }
.tool-app-saltroute .sr-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 12px; }
.tool-app-saltroute .sr-stat { background: #ecfeff; border: 1px solid #a5f3fc; border-radius: 12px; padding: 12px; text-align: center; }
.tool-app-saltroute .sr-stat-n { display: block; font-size: 26px; font-weight: 800; color: #0e7490; }
.tool-app-saltroute .sr-stat-bad { background: #fef2f2; border-color: #fecaca; }
.tool-app-saltroute .sr-stat-bad .sr-stat-n { color: #b91c1c; }
.tool-app-saltroute .sr-actions { display: flex; gap: 8px; flex-wrap: wrap; margin: 10px 0; }
.tool-app-saltroute .sr-btn { background: #0e7490; color: #fff; border: none; border-radius: 10px; padding: 9px 16px; font-size: 13px; font-weight: 700; cursor: pointer; }
.tool-app-saltroute .sr-btn:hover { background: #155e75; }
.tool-app-saltroute .sr-btn-ghost { background: #ecfeff; color: #0e7490; }
.tool-app-saltroute .sr-btn-ghost:hover { background: #cffafe; }
.tool-app-saltroute .sr-btn-sm { padding: 5px 10px; font-size: 12px; }
.tool-app-saltroute .sr-routelist, .tool-app-saltroute .sr-custlist, .tool-app-saltroute .sr-history { list-style: none; padding: 0; margin: 8px 0; }
.tool-app-saltroute .sr-stop { background: #f0fdfa; border: 1px solid #a5f3fc; border-left: 5px solid #0e7490; border-radius: 10px; padding: 10px 12px; margin-bottom: 8px; display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; }
.tool-app-saltroute .sr-stop.sr-overdue { border-left-color: #b91c1c; background: #fef2f2; border-color: #fecaca; }
.tool-app-saltroute .sr-stop-name { font-weight: 700; }
.tool-app-saltroute .sr-stop-detail { font-size: 12px; color: #475569; }
.tool-app-saltroute .sr-badge { font-size: 11px; font-weight: 700; padding: 3px 9px; border-radius: 999px; background: #cffafe; color: #0e7490; white-space: nowrap; }
.tool-app-saltroute .sr-overdue .sr-badge { background: #fecaca; color: #991b1b; }
.tool-app-saltroute .sr-empty { color: #64748b; padding: 14px; background: #f8fafc; border-radius: 10px; }
.tool-app-saltroute .sr-form { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 10px; margin-bottom: 8px; }
.tool-app-saltroute .sr-form label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-saltroute .sr-form input[type="text"], .tool-app-saltroute .sr-form input[type="number"], .tool-app-saltroute .sr-form input[type="date"], .tool-app-saltroute .sr-form select { border: 1px solid #a5f3fc; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; }
.tool-app-saltroute .sr-form button { grid-column: 1 / -1; justify-self: start; }
.tool-app-saltroute .sr-cust { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 10px 12px; margin-bottom: 8px; }
.tool-app-saltroute .sr-cust-top { display: flex; justify-content: space-between; align-items: center; gap: 8px; flex-wrap: wrap; }
.tool-app-saltroute .sr-cust-name { font-weight: 700; }
.tool-app-saltroute .sr-cust-detail { font-size: 12px; color: #475569; margin-top: 4px; }
.tool-app-saltroute .sr-cust-actions { display: flex; gap: 6px; margin-top: 8px; }
.tool-app-saltroute .sr-del { background: none; border: none; color: #b91c1c; cursor: pointer; font-size: 12px; font-weight: 600; }
.tool-app-saltroute .sr-history li { background: #f8fafc; border-radius: 8px; padding: 8px 12px; margin-bottom: 6px; font-size: 13px; }
.tool-app-saltroute .sr-modal { position: fixed; inset: 0; background: rgba(8, 51, 68, 0.5); display: flex; align-items: center; justify-content: center; z-index: 50; padding: 16px; }
.tool-app-saltroute .sr-modal-box { background: #fff; border-radius: 14px; padding: 20px; max-width: 420px; width: 100%; }
.tool-app-saltroute .sr-modal-box h4 { margin-top: 0; }
.tool-app-saltroute .sr-modal-box label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; margin-bottom: 10px; }
.tool-app-saltroute .sr-modal-box label.sr-check { flex-direction: row; align-items: center; gap: 8px; font-size: 14px; }
.tool-app-saltroute .sr-modal-box input[type="text"], .tool-app-saltroute .sr-modal-box input[type="date"], .tool-app-saltroute .sr-modal-box input[type="number"] { border: 1px solid #a5f3fc; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; }
.tool-app-saltroute .sr-visitfor { font-weight: 700; margin: 0 0 12px; }

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  var root = $('toolAppRoot');
  var LS_KEY = 'toolapp-saltroute-data';
  var DAY = 86400000;
  var visitTarget = null;

  function todayStr() {
    var d = new Date();
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  }
  function parseDay(s) {
    var p = String(s || '').split('-');
    if (p.length !== 3) return null;
    var d = new Date(parseInt(p[0], 10), parseInt(p[1], 10) - 1, parseInt(p[2], 10));
    return isNaN(d.getTime()) ? null : d;
  }
  function fmtDay(d) {
    return (d.getMonth() + 1) + '/' + d.getDate() + '/' + d.getFullYear();
  }
  function addDays(s, n) {
    var d = parseDay(s);
    if (!d) return null;
    return new Date(d.getTime() + (parseInt(n, 10) || 0) * DAY);
  }
  function daysUntil(d) {
    var now = parseDay(todayStr());
    return Math.round((d.getTime() - now.getTime()) / DAY);
  }

  function getData() {
    try {
      var d = JSON.parse(localStorage.getItem(LS_KEY));
      if (d && Array.isArray(d.customers)) return d;
    } catch (e) {}
    return { customers: [], visits: [] };
  }
  function setData(d) {
    try { localStorage.setItem(LS_KEY, JSON.stringify(d)); } catch (e) {}
  }
  function newId() { return 'sr' + Date.now().toString(36) + Math.floor(Math.random() * 999); }
  function findCustomer(id) {
    var cs = getData().customers;
    for (var i = 0; i < cs.length; i++) if (cs[i].id === id) return cs[i];
    return null;
  }

  function routeStops() {
    var data = getData();
    var stops = [];
    for (var i = 0; i < data.customers.length; i++) {
      var c = data.customers[i];
      var jobs = [];
      var sd = c.lastSalt ? addDays(c.lastSalt, c.saltDays) : parseDay(todayStr());
      var fd = c.lastFilter ? addDays(c.lastFilter, c.filterDays) : null;
      if (sd && daysUntil(sd) <= 7) jobs.push({ kind: 'Salt delivery', due: sd });
      if (fd && daysUntil(fd) <= 7) jobs.push({ kind: 'Filter change', due: fd });
      for (var j = 0; j < jobs.length; j++) {
        stops.push({ cust: c, kind: jobs[j].kind, due: jobs[j].due, late: daysUntil(jobs[j].due) < 0 });
      }
    }
    stops.sort(function (a, b) { return a.due.getTime() - b.due.getTime(); });
    return stops;
  }

  function dueLabel(d) {
    var n = daysUntil(d);
    if (n < 0) return 'Overdue by ' + (-n) + (n === -1 ? ' day' : ' days');
    if (n === 0) return 'Due today';
    if (n === 1) return 'Due tomorrow';
    return 'Due in ' + n + ' days';
  }

  function renderStats() {
    var stops = routeStops();
    var overdue = 0;
    for (var i = 0; i < stops.length; i++) if (stops[i].late) overdue++;
    $('sr-stat-overdue').textContent = overdue;
    $('sr-stat-week').textContent = stops.length;
    $('sr-stat-customers').textContent = getData().customers.length;
  }

  function renderRoute() {
    var stops = routeStops();
    var ul = $('sr-route');
    ul.innerHTML = '';
    if (!stops.length) {
      var li = document.createElement('li');
      li.className = 'sr-empty';
      li.textContent = 'No stops due in the next 7 days. Add customers and log visits to build your route.';
      ul.appendChild(li);
      return;
    }
    for (var i = 0; i < stops.length; i++) {
      var s = stops[i];
      var item = document.createElement('li');
      item.className = 'sr-stop' + (s.late ? ' sr-overdue' : '');
      var info = document.createElement('div');
      info.innerHTML =
        '<div class="sr-stop-name">' + esc(s.cust.name) + '</div>' +
        '<div class="sr-stop-detail">' + esc(s.kind) + ' &middot; ' + esc(s.cust.eq || '') +
        (s.cust.addr ? ' &middot; ' + esc(s.cust.addr) : '') +
        (s.cust.phone ? ' &middot; ' + esc(s.cust.phone) : '') + '</div>';
      var badge = document.createElement('span');
      badge.className = 'sr-badge';
      badge.textContent = dueLabel(s.due) + ' (' + fmtDay(s.due) + ')';
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'sr-btn sr-btn-sm';
      btn.textContent = 'Log visit';
      btn.setAttribute('data-sr-visit', s.cust.id);
      var wrap = document.createElement('div');
      wrap.appendChild(badge);
      wrap.appendChild(btn);
      item.appendChild(info);
      item.appendChild(wrap);
      ul.appendChild(item);
    }
  }

  function renderCustomers() {
    var data = getData();
    var ul = $('sr-customers');
    ul.innerHTML = '';
    if (!data.customers.length) {
      var li = document.createElement('li');
      li.className = 'sr-empty';
      li.textContent = 'No customers yet. Add your first customer above, or load sample data from the Route tab.';
      ul.appendChild(li);
      return;
    }
    for (var i = 0; i < data.customers.length; i++) {
      var c = data.customers[i];
      var item = document.createElement('li');
      item.className = 'sr-cust';
      var sd = c.lastSalt ? addDays(c.lastSalt, c.saltDays) : null;
      var fd = c.lastFilter ? addDays(c.lastFilter, c.filterDays) : null;
      var top = document.createElement('div');
      top.className = 'sr-cust-top';
      var name = document.createElement('span');
      name.className = 'sr-cust-name';
      name.textContent = c.name;
      var act = document.createElement('div');
      act.className = 'sr-cust-actions';
      var visit = document.createElement('button');
      visit.type = 'button';
      visit.className = 'sr-btn sr-btn-sm';
      visit.textContent = 'Log visit';
      visit.setAttribute('data-sr-visit', c.id);
      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'sr-del';
      del.textContent = 'Remove';
      del.setAttribute('data-sr-del', c.id);
      act.appendChild(visit);
      act.appendChild(del);
      top.appendChild(name);
      top.appendChild(act);
      var det = document.createElement('div');
      det.className = 'sr-cust-detail';
      det.textContent =
        [c.eq, c.model ? 'Model ' + c.model : '', c.serial ? 'SN ' + c.serial : ''].filter(Boolean).join(' | ') +
        (c.addr ? ' | ' + c.addr : '') + (c.phone ? ' | ' + c.phone : '') +
        ' | Salt due ' + (sd ? fmtDay(sd) : 'now') + ' | Filter due ' + (fd ? fmtDay(fd) : 'unknown');
      item.appendChild(top);
      item.appendChild(det);
      ul.appendChild(item);
    }
  }

  function renderHistory() {
    var data = getData();
    var ul = $('sr-history');
    ul.innerHTML = '';
    var v = data.visits.slice().sort(function (a, b) { return a.date < b.date ? 1 : -1; }).slice(0, 100);
    if (!v.length) {
      var li = document.createElement('li');
      li.className = 'sr-empty';
      li.textContent = 'No visits logged yet.';
      ul.appendChild(li);
      return;
    }
    for (var i = 0; i < v.length; i++) {
      var item = document.createElement('li');
      var c = findCustomer(v[i].custId);
      item.textContent =
        (v[i].date || '') + ' — ' + (c ? c.name : 'Unknown') +
        ' — ' + v[i].bags + (v[i].bags === 1 ? ' bag' : ' bags') + ' salt' +
        (v[i].filter ? ', filter changed' : '') +
        (v[i].notes ? ' — ' + v[i].notes : '');
      ul.appendChild(item);
    }
  }

  function renderAll() {
    renderStats();
    renderRoute();
    renderCustomers();
    renderHistory();
  }

  function openVisit(custId) {
    var c = findCustomer(custId);
    if (!c) return;
    visitTarget = custId;
    $('sr-visitfor').textContent = c.name + (c.addr ? ' — ' + c.addr : '');
    $('sr-v-date').value = todayStr();
    $('sr-v-bags').value = 4;
    $('sr-v-filter').checked = false;
    $('sr-v-notes').value = '';
    $('sr-modal').classList.remove('sr-hidden');
  }
  function closeVisit() {
    visitTarget = null;
    $('sr-modal').classList.add('sr-hidden');
  }
  function saveVisit() {
    var data = getData();
    var c = null;
    for (var i = 0; i < data.customers.length; i++) if (data.customers[i].id === visitTarget) c = data.customers[i];
    if (!c) { closeVisit(); return; }
    var date = $('sr-v-date').value || todayStr();
    var bags = parseInt($('sr-v-bags').value, 10) || 0;
    var filt = $('sr-v-filter').checked;
    if (bags > 0) c.lastSalt = date;
    if (filt) c.lastFilter = date;
    data.visits.unshift({ custId: c.id, date: date, bags: bags, filter: filt, notes: $('sr-v-notes').value });
    data.visits = data.visits.slice(0, 500);
    setData(data);
    closeVisit();
    renderAll();
  }

  function exportCSV() {
    var stops = routeStops();
    var rows = [['Name', 'Address', 'Phone', 'Job', 'Due date', 'Equipment']];
    for (var i = 0; i < stops.length; i++) {
      var s = stops[i];
      rows.push([
        s.cust.name, s.cust.addr || '', s.cust.phone || '', s.kind,
        s.due.getFullYear() + '-' + String(s.due.getMonth() + 1).padStart(2, '0') + '-' + String(s.due.getDate()).padStart(2, '0'),
        s.cust.eq || ''
      ]);
    }
    var csv = rows.map(function (r) {
      return r.map(function (cell) { return '"' + String(cell).replace(/"/g, '""') + '"'; }).join(',');
    }).join('\r\n');
    var blob = new Blob([csv], { type: 'text/csv' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'saltroute-route-' + todayStr() + '.csv';
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { document.body.removeChild(a); URL.revokeObjectURL(a.href); }, 500);
  }

  function loadSample() {
    var t = todayStr();
    var d = function (daysAgo) { var x = parseDay(t); return new Date(x.getTime() - daysAgo * DAY); };
    var iso = function (d) { return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); };
    var data = {
      customers: [
        { id: newId(), name: 'Bobby Alvarez', addr: '742 Pine Hollow Rd, Garland, TX', phone: '(972) 555-0148', eq: 'Water softener', model: 'Kinetico K5', serial: 'KS-884120', saltDays: 45, filterDays: 180, lastSalt: iso(d(48)), lastFilter: iso(d(120)) },
        { id: newId(), name: 'Priya Natarajan', addr: '118 Shoreline Dr, Rowlett, TX', phone: '(214) 555-0192', eq: 'Whole-house filter', model: 'Culligan Medallist', serial: 'CM-552017', saltDays: 60, filterDays: 180, lastSalt: iso(d(57)), lastFilter: iso(d(176)) },
        { id: newId(), name: 'Tom Kowalski', addr: '9050 Farmstead Ln, Sachse, TX', phone: '(469) 555-0117', eq: 'Water softener', model: 'EcoWater ERR3502', serial: 'EW-310954', saltDays: 45, filterDays: 365, lastSalt: iso(d(20)), lastFilter: iso(d(200)) },
        { id: newId(), name: 'Dana Whitfield', addr: '27 Meadowbrook Ct, Wylie, TX', phone: '(972) 555-0163', eq: 'RO system', model: 'Kinetico K5 Drinking Water', serial: 'K5-773021', saltDays: 90, filterDays: 180, lastSalt: iso(d(88)), lastFilter: iso(d(90)) }
      ],
      visits: []
    };
    setData(data);
    renderAll();
  }

  root.addEventListener('click', function (e) {
    var t = e.target;
    if (t.classList && t.classList.contains('sr-tab')) {
      var tabs = root.querySelectorAll('.sr-tab');
      for (var i = 0; i < tabs.length; i++) tabs[i].classList.remove('sr-active');
      t.classList.add('sr-active');
      var panels = root.querySelectorAll('.sr-panel');
      for (var j = 0; j < panels.length; j++) {
        panels[j].classList.toggle('sr-hidden', panels[j].getAttribute('data-sr-panel') !== t.getAttribute('data-sr-tab'));
      }
      return;
    }
    if (t.id === 'sr-export') { exportCSV(); return; }
    if (t.id === 'sr-sample') { loadSample(); return; }
    if (t.id === 'sr-v-save') { saveVisit(); return; }
    if (t.id === 'sr-v-cancel') { closeVisit(); return; }
    var vid = t.getAttribute && t.getAttribute('data-sr-visit');
    if (vid) { openVisit(vid); return; }
    var did = t.getAttribute && t.getAttribute('data-sr-del');
    if (did) {
      var data = getData();
      data.customers = data.customers.filter(function (c) { return c.id !== did; });
      data.visits = data.visits.filter(function (v) { return v.custId !== did; });
      setData(data);
      renderAll();
    }
  });

  $('sr-addform').addEventListener('submit', function (e) {
    e.preventDefault();
    var data = getData();
    data.customers.push({
      id: newId(),
      name: $('sr-f-name').value.trim(),
      addr: $('sr-f-addr').value.trim(),
      phone: $('sr-f-phone').value.trim(),
      eq: $('sr-f-eq').value,
      model: $('sr-f-model').value.trim(),
      serial: $('sr-f-serial').value.trim(),
      saltDays: Math.max(1, parseInt($('sr-f-saltdays').value, 10) || 45),
      filterDays: Math.max(1, parseInt($('sr-f-filterdays').value, 10) || 180),
      lastSalt: $('sr-f-lastsalt').value || '',
      lastFilter: $('sr-f-lastfilter').value || ''
    });
    setData(data);
    $('sr-addform').reset();
    $('sr-f-saltdays').value = 45;
    $('sr-f-filterdays').value = 180;
    renderAll();
  });

  renderAll();
})();
